# v2.2 Item 6 (PREREGISTRATION.md): summarise logs/warnings.log (written by the Rmd warning hook and logw()) into
# logs/WARNINGS_EXPLAINED.md. Each distinct warning type is matched to a written explanation below; a type without an
# explanation is listed as UNEXPLAINED and the script exits with status 1.
suppressMessages(library(data.table))
cfg <- yaml::read_yaml(Sys.getenv("P6_CONFIG", "config.yaml")); ROOT <- cfg$paths$root
x <- readLines(file.path(ROOT, "logs", "warnings.log"), warn = FALSE, encoding = "UTF-8"); x <- x[nzchar(trimws(x))]
W <- data.table(where = sub("^\\[([^]]*)\\].*$", "\\1", x), msg = trimws(sub("^\\[[^]]*\\] *", "", x)))
EXPL <- fread(file.path(ROOT, "logs", "warning_explanations.csv"), encoding = "UTF-8")   # pattern, explanation, action
W[, type := { k <- vapply(msg, function(m) { i <- which(vapply(EXPL$pattern, function(p) grepl(p, m, perl = TRUE), TRUE)); if (length(i)) i[1] else NA_integer_ }, 1L); k }]
S <- W[, .(n = .N, where = paste(head(unique(where), 6), collapse = "; "), example = msg[1]), by = type][order(-n)]
S[, `:=`(explanation = fifelse(is.na(type), "UNEXPLAINED", EXPL$explanation[type]), action = fifelse(is.na(type), "", EXPL$action[type]))]
md <- c("# Warnings of the analysis run (generated by scripts/18_explain_warnings.R)", "",
        paste0("Total warnings logged: ", nrow(W), "; distinct types: ", nrow(S), ". No warning is suppressed in the code; every warning is written to `logs/warnings.log`."), "",
        "| n | where (chunk / call) | example | explanation | action |", "|---|---|---|---|---|",
        sprintf("| %d | %s | %s | %s | %s |", S$n, S$where, gsub("\\|", "/", substr(S$example, 1, 160)), S$explanation, S$action))
writeLines(enc2utf8(md), file.path(ROOT, "logs", "WARNINGS_EXPLAINED.md"), useBytes = TRUE)
cat("warnings:", nrow(W), "| types:", nrow(S), "| unexplained:", sum(is.na(S$type)), "\n")
if (any(is.na(S$type))) { print(S[is.na(type), .(n, where, example)]); quit(status = 1) }
